practice.solution:
#include <iostream>
#include <string>

int main() {
    std::string product = "Notebook";
    int quantity = 3;
    double price = 4.75;
    char currency = '$';

    std::cout << quantity << " x " << product << " at " << currency << price << " each\n";
    return 0;
}

example.code:
#include <iomanip>
#include <iostream>

int main() {
    double total = 1234567.891;
    double pi = 3.14159265;

    std::cout << total << '\n';
    std::cout << std::fixed << std::setprecision(2) << total << '\n';
    std::cout << std::setprecision(4) << pi << '\n';
    return 0;
}

