}

example.code:
#include <iomanip>
#include <iostream>

int main() {
    int orderNumber = 42;

    std::cout << std::fixed << std::setprecision(2);
    std::cout << std::left << std::setw(10) << "Apple" << std::right << std::setw(8) << 0.5 << '\n';
    std::cout << std::left << std::setw(10) << "Bread" << std::right << std::setw(8) << 2.25 << '\n';
    std::cout << std::left << std::setw(10) << "Cheese" << std::right << std::setw(8) << 12.8 << '\n';
    std::cout << "Order #" << std::right << std::setfill('0') << std::setw(5) << orderNumber << '\n';
    return 0;
}

