practice.solution:
#include <iomanip>
#include <iostream>

int main() {
    int hours = 7;
    int minutes = 5;

    std::cout << std::left << std::setw(8) << "Mia" << std::right << std::setw(5) << 120 << '\n';
    std::cout << std::left << std::setw(8) << "Leo" << std::right << std::setw(5) << 95 << '\n';
    std::cout << std::left << std::setw(8) << "Zoe" << std::right << std::setw(5) << 7 << '\n';
    std::cout << std::right << std::setfill('0') << std::setw(2) << hours << ':' << std::setw(2) << minutes << '\n';
    return 0;
}
